    ```csharp
    using System.Data;
    using Microsoft.EntityFrameworkCore;
    using seed_b_backend.Api.Data;
    using seed_b_backend.Api.Domain;

    namespace seed_b_backend.Api.Application;

    public class OrderService(AppDbContext context)
    {
        public async Task<OrderPlacementResult> PlaceOrderAsync(
            Guid? cartId,
            string customerName,
            string deliveryAddress,
            string email,
            CancellationToken ct = default)
        {
            if (cartId is null)
            {
                return new OrderPlacementResult { Status = OrderPlacementStatus.CartEmpty };
            }

            var lines = await context.CartItems
                .Where(ci => ci.CartId == cartId)
                .Select(ci => new { ci.ProductId, ci.SupplierId, ci.Quantity })
                .ToListAsync(ct);

            if (lines.Count == 0)
            {
                return new OrderPlacementResult { Status = OrderPlacementStatus.CartEmpty };
            }

            var invalidQuantityLines = lines
                .Where(l => l.Quantity < 1)
                .Select(l => new OrderLineRejection
                {
                    ProductId = l.ProductId,
                    SupplierId = l.SupplierId,
                    Reason = OrderLineRejectionReason.InvalidQuantity
                })
                .ToList();
            if (invalidQuantityLines.Count > 0)
            {
                return new OrderPlacementResult { Status = OrderPlacementStatus.LinesRejected, RejectedLines = invalidQuantityLines };
            }

            await using var transaction = await context.Database.BeginTransactionAsync(IsolationLevel.Serializable, ct);

            var offerPrices = new Dictionary<(string ProductId, string SupplierId), decimal>();
            var offerGoneLines = new List<OrderLineRejection>();
            foreach (var line in lines)
            {
                var price = await context.Offers
                    .Where(o => o.ProductId == line.ProductId && o.SupplierId == line.SupplierId)
                    .Select(o => (decimal?)o.Price)
                    .SingleOrDefaultAsync(ct);

                if (price is null)
                {
                    offerGoneLines.Add(new OrderLineRejection
                    {
                        ProductId = line.ProductId,
                        SupplierId = line.SupplierId,
                        Reason = OrderLineRejectionReason.OfferGone
                    });
                }
                else
                {
                    offerPrices[(line.ProductId, line.SupplierId)] = price.Value;
                }
            }

            if (offerGoneLines.Count > 0)
            {
                await transaction.RollbackAsync(ct);
                return new OrderPlacementResult { Status = OrderPlacementStatus.LinesRejected, RejectedLines = offerGoneLines };
            }

            var order = new Order
            {
                Id = Guid.NewGuid(),
                CustomerName = customerName,
                DeliveryAddress = deliveryAddress,
                Email = email
            };
            context.Orders.Add(order);

            foreach (var line in lines)
            {
                context.OrderItems.Add(new OrderItem
                {
                    OrderId = order.Id,
                    ProductId = line.ProductId,
                    SupplierId = line.SupplierId,
                    Quantity = line.Quantity,
                    UnitPrice = offerPrices[(line.ProductId, line.SupplierId)]
                });
            }

            await context.SaveChangesAsync(ct);
            await context.CartItems.Where(ci => ci.CartId == cartId).ExecuteDeleteAsync(ct);
            await transaction.CommitAsync(ct);

            return new OrderPlacementResult
            {
                Status = OrderPlacementStatus.Success,
                Order = await BuildOrderResultAsync(order.Id, ct)
            };
        }

        private async Task<OrderResult> BuildOrderResultAsync(Guid orderId, CancellationToken ct)
        {
            var order = await context.Orders.SingleAsync(o => o.Id == orderId, ct);
            var lines = await context.OrderItems
                .Where(oi => oi.OrderId == orderId)
                .Select(oi => new OrderResultLine
                {
                    ProductId = oi.ProductId,
                    ProductName = oi.Product!.Name,
                    SupplierId = oi.SupplierId,
                    SupplierName = oi.Supplier!.Name,
                    Quantity = oi.Quantity,
                    UnitPrice = oi.UnitPrice
                })
                .ToListAsync(ct);

            return new OrderResult
            {
                OrderId = order.Id,
                Status = order.Status,
                Items = lines,
                TotalPrice = lines.Sum(l => l.UnitPrice * l.Quantity)
            };
        }
    }
    ```
    - **Prüfreihenfolge ist bewusst und nicht vertauschbar (AC 3 vs. AC 4):** Leerer Warenkorb und unzulässige Menge werden **vor** `BeginTransactionAsync` per einfachem Read geprüft (AD-3: „Before opening a transaction, order placement rejects immediately if the cart has zero lines or any line has an invalid quantity"); die `Offer`-Existenz wird **erst danach**, innerhalb der sperrenden Transaktion, geprüft (AD-3: „re-reads exactly the Offer rows … using a locking/serializable read"). **Konsequenz, nicht Fehler:** Enthält ein Warenkorb gleichzeitig eine Zeile mit unzulässiger Menge UND eine Zeile mit entferntem Angebot, meldet die Antwort ausschließlich die Mengen-Verletzung(en) — der Angebots-Check läuft nie, weil die Methode vorher zurückkehrt. Das ist die von AD-3 vorgegebene Reihenfolge, keine unvollständige Fehlererkennung.
    - **Pro-Zeile-Query statt eines einzelnen `Contains`/`Contains`-Filters für die `Offer`-Lesung:** Ein naiver `Where(o => productIds.Contains(o.ProductId) && supplierIds.Contains(o.SupplierId))` würde bei mehreren Warenkorbzeilen ein falsches Kreuzprodukt matchen (z. B. träfe er bei Zeilen `(P1,S1)` und `(P2,S2)` fälschlich auch ein existierendes, aber nicht im Warenkorb befindliches Angebot `(P1,S2)`). Die Schleife mit `ProductId == line.ProductId && SupplierId == line.SupplierId` pro Zeile vermeidet diesen Fehler; mehrere kleine Queries innerhalb derselben `Serializable`-Transaktion sind bezüglich der Sperrsemantik äquivalent zu einer einzigen Batch-Query — jede gelesene Zeile wird unter `Serializable`-Isolationsebene bis zum Commit gesperrt/überwacht (identische Garantie wie ein `WITH (UPDLOCK, HOLDLOCK)`-Batch-Read), nur mit mehreren Round-Trips statt einem. Beim aktuellen kleinen Referenzdatenbestand unkritisch (NFR4-Platzhalter).
    - **`IsolationLevel.Serializable` statt roher `WITH (UPDLOCK, HOLDLOCK)`-SQL-Hints:** AD-3 nennt beide Optionen explizit gleichwertig („e.g. a locking read such as `WITH (UPDLOCK, HOLDLOCK)`, or `IsolationLevel.Serializable`"); `IsolationLevel.Serializable` ist provider-neutral (funktioniert identisch gegen SQL Server in Produktion und SQLite in Tests, siehe Task 3), während rohe T-SQL-Hints nur gegen SQL Server liefen und die bestehende SQLite-Testinfrastruktur (Story 1.1–3.2) gebrochen hätten.
    - **`ExecuteDeleteAsync` auf `CartItems` läuft innerhalb derselben Transaktion wie `Order`/`OrderItem`, nicht danach:** Die PRD formuliert „wird der Warenkorb im Anschluss vollständig geleert" (zeitlich nach der Bestellanlage), aber AD-3 fordert nur explizit Atomarität für `Order`+`OrderItem`. Diese Story geht bewusst einen Schritt weiter und schließt das Leeren in dieselbe Transaktion ein — verhindert einen Zwischenzustand, in dem eine Bestellung bereits committet, der Warenkorb aber (z. B. durch einen Absturz zwischen den beiden Schritten) noch mit denselben, jetzt bereits bestellten Positionen gefüllt ist. Kein AD-3-Verstoß (stärkere, nicht schwächere Garantie), konsistent mit dem Prinzip „das System muss Ende-zu-Ende funktionsfähig bleiben, nicht nur die wörtlichen ACs erfüllen".
    - **`CartId`-Feld/`Cart`-Zeile selbst wird nicht gelöscht, nur die `CartItem`-Zeilen:** „Warenkorb wird geleert" (PRD) bedeutet 0 Positionen, nicht Löschung des `Cart`-Datensatzes — identische Cart-Identität (`X-Cart-Id`) bleibt für den Gast gültig und liefert danach über `GET /api/cart` (Story 3.2) korrekt einen leeren Warenkorb zurück, kein neuer Header-Wert nötig.
    - **Kein `DbUpdateException`-Race-Fallback wie bei `CartService.AddItemAsync`/`RatingService.SubmitRatingAsync`:** Es gibt hier keinen App-seitigen Check-then-Insert-Unique-Constraint-Konflikt — `Order.Id`/`OrderItem`-Primärschlüssel werden serverseitig frisch generiert (`Guid.NewGuid()`), keine zwei gleichzeitigen Bestellabschlüsse können denselben `OrderId` treffen. Die einzige Race-Gefahr (konkurrierende Änderung an einem referenzierten `Offer`) wird bereits durch die `Serializable`-Transaktion selbst abgedeckt, kein zusätzlicher Fallback-Zweig nötig.

