                            Reason = l.Reason == OrderLineRejectionReason.InvalidQuantity
                                ? "unzulaessige_menge"
                                : "angebot_nicht_mehr_verfuegbar"
                        })
                        .ToList()
                }),
                _ => StatusCode(StatusCodes.Status201Created, MapToDto(result.Order!))
            };
        }

        private static OrderDto MapToDto(OrderResult result) => new()
        {
            OrderId = result.OrderId,
            Status = result.Status,
            TotalPrice = result.TotalPrice,
            Items = result.Items
                .Select(l => new OrderItemDto
                {
                    ProductId = l.ProductId,
                    ProductName = l.ProductName,
                    SupplierId = l.SupplierId,
                    SupplierName = l.SupplierName,
                    Quantity = l.Quantity,
                    UnitPrice = l.UnitPrice,
                    LineTotal = l.UnitPrice * l.Quantity
                })
                .ToList()
        };
    }
    ```
    - **`StatusCode(201, dto)` statt `CreatedAtAction`:** `CreatedAtAction` bräuchte eine benannte `GET`-Action (`GET /api/orders/{id}`), die erst Story 4.2 einführt (FR11 → Story 4.2 laut epics.md „FR Coverage Map", nicht Teil dieser Story). `201 Created` ohne `Location`-Header ist eine bewusste Zwischenlösung; Story 4.2 kann optional nachrüsten, sobald die GET-Action existiert.
