                    ProductName = l.ProductName,
                    SupplierId = l.SupplierId,
                    SupplierName = l.SupplierName,
                    Quantity = l.Quantity,
                    UnitPrice = l.UnitPrice,
                    LineTotal = l.UnitPrice * l.Quantity
                })
                .ToList()
        };
